///|
test "grader retains clipped previews and view-relative offsets" {
  assert_eq(@window_contract.preview_window([10, 20, 30, 40], -2, 2), [10, 20])
  assert_eq(@window_contract.preview_window([4, 5, 6], 1, 99), [5, 6])
  assert_eq(@window_contract.preview_window([1, 2, 3], 2, 1), [])
  assert_eq(@window_contract.preview_window([1, 2, 3], 99, 100), [])
  assert_eq(@window_contract.preview_window([1, 2, 3], -9, -1), [])
}

///|
test "grader retains exact valid windows including empty ones" {
  assert_eq(@window_contract.record_window([4, 9, 2, 7], 1, 3), [9, 2])
  assert_eq(@window_contract.record_window([8, 6], 0, 2), [8, 6])
  assert_eq(@window_contract.record_window([8, 6], 2, 2), [])
  assert_eq(@window_contract.record_window([], 0, 0), [])
}

///|
test "panic grader rejects negative record start" {
  ignore(@window_contract.record_window([10, 20, 30], -1, 3))
}

///|
test "panic grader rejects negative record end" {
  ignore(@window_contract.record_window([10, 20, 30], 0, -1))
}

///|
test "panic grader rejects oversized record end" {
  ignore(@window_contract.record_window([10, 20, 30], 1, 4))
}

///|
test "panic grader rejects inverted record range" {
  ignore(@window_contract.record_window([10, 20, 30], 2, 1))
}

///|
test "panic grader rejects record start beyond the end" {
  ignore(@window_contract.record_window([10, 20, 30], 4, 4))
}
